"""DuckDB analytics over stored Parquet datasets."""

from __future__ import annotations

from .storage import MarketDataStore


def summarize_parquet(store: MarketDataStore, ticker: str) -> dict:
    """Calculate compact metrics from one store-managed Parquet file."""
    import duckdb
    path = store._directory(ticker) / "daily.parquet"
    if not path.is_file(): raise FileNotFoundError(f"No stored market data found for {ticker}")
    # Path is generated by the validated store, then quoted as a SQL string literal.
    escaped = str(path).replace("'", "''")
    query = f"""SELECT count(*) AS row_count, min(date) AS first_date, max(date) AS last_date,
        avg(close) AS average_close, min(close) AS minimum_close, max(close) AS maximum_close,
        avg(ln(close / lag_close)) AS mean_daily_log_return,
        stddev_samp(ln(close / lag_close)) AS daily_volatility
        FROM (SELECT date, close, lag(close) OVER (ORDER BY date) AS lag_close FROM read_parquet('{escaped}'))"""
    try:
        row = duckdb.connect().execute(query).fetchone()
        return dict(zip(["row_count", "first_date", "last_date", "average_close", "minimum_close", "maximum_close", "mean_daily_log_return", "daily_volatility"], row))
    except Exception as exc:
        raise ValueError(f"DuckDB could not analyze {ticker}: {exc}") from exc
